.grid{width:100%;height:100%;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));grid-auto-rows:1fr;gap:clamp(10px,1.2vw,22px);align-content:center}.grid.compact{grid-template-columns:repeat(5,minmax(0,1fr))}
.card{min-width:0;background:var(--card);border:1px solid var(--line);border-radius:clamp(14px,1.5vw,28px);padding:clamp(12px,1.5vw,26px);display:grid;place-items:center;text-align:center;box-shadow:0 15px 38px #0002;overflow:hidden}.card .kicker{font-size:clamp(11px,.85vw,16px);font-weight:900;letter-spacing:.12em;color:var(--accent);text-transform:uppercase}.card strong{display:block;font-size:clamp(20px,2vw,40px);line-height:1.08;max-width:100%}.card small{display:block;color:var(--muted);font-size:clamp(12px,1.05vw,20px);margin-top:.45em}.bib{font-size:clamp(48px,6vw,112px)!important;line-height:.9!important;color:var(--accent)}
.judge-card{border-top:5px solid var(--warn)}.judge-card.submitted{border-top-color:var(--good)}.judge-card .status{margin-top:.8em;border-radius:999px;padding:.4em .8em;background:#0002;font-weight:800;text-transform:uppercase}
.progress-wrap{width:100%;height:100%;display:flex;flex-direction:column;gap:2vh}.progress-summary{display:flex;justify-content:center;gap:4vw;font-size:clamp(18px,2vw,36px);font-weight:900}.progress-summary b{color:var(--good)}.progress-summary .waiting{color:var(--warn)}
.board{width:min(1500px,96vw);max-height:100%;overflow:hidden;border:1px solid var(--line);border-radius:24px;background:var(--card);box-shadow:0 18px 55px #0002}.rank-row{display:grid;grid-template-columns:clamp(55px,6vw,105px) clamp(42px,4.2vw,74px) clamp(95px,10vw,175px) 1fr clamp(110px,13vw,220px);gap:18px;align-items:center;padding:clamp(8px,1vh,15px) clamp(15px,1.8vw,30px);border-bottom:1px solid var(--line);font-size:clamp(16px,1.5vw,29px)}.rank-row:last-child{border:0}.rank-row .place{font-weight:1000;color:var(--accent)}.rank-row .number{font-weight:900}.rank-row .name{font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.rank-row .score{text-align:right;font-weight:1000}
.podium{width:min(1500px,96vw);height:100%;display:grid;grid-template-columns:1fr 1.15fr 1fr;align-items:end;gap:2vw;padding:3vh 0}.podium-card{background:var(--card);border:1px solid var(--line);border-radius:28px 28px 10px 10px;text-align:center;padding:3vh 1.5vw;box-shadow:0 18px 55px #0003}.podium-card.first{min-height:75%;border:3px solid #f2c94c}.podium-card.second{min-height:62%;border:2px solid #cbd5e1}.podium-card.third{min-height:54%;border:2px solid #cd7f32}.podium-card .medal{font-size:clamp(42px,6vw,110px)}.podium-card .place{font-size:clamp(20px,2vw,40px);font-weight:1000}.podium-card .number{font-size:clamp(30px,4vw,74px);font-weight:1000;color:var(--accent)}.podium-card .name{font-size:clamp(20px,2.2vw,44px);font-weight:800}.podium-card .score{color:var(--muted);font-size:clamp(16px,1.5vw,28px)}
.empty{text-align:center;color:var(--muted)}.empty strong{display:block;color:var(--text);font-size:clamp(38px,5vw,90px)}.empty span{font-size:clamp(18px,2vw,38px)}
.footer{min-height:30px;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;color:var(--muted);font-size:clamp(10px,.85vw,16px);letter-spacing:.08em;text-transform:uppercase}.footer .state{text-align:left}.footer .page{text-align:center}.footer .live{text-align:right;color:var(--good);font-weight:900}.dot{display:inline-block;width:.65em;height:.65em;border-radius:50%;background:currentColor;margin-right:.45em}
.connection{position:fixed;right:clamp(14px,1.8vw,34px);bottom:clamp(14px,1.8vw,34px);z-index:9;border-radius:999px;background:#9f1239;color:#fff;padding:.72em 1.05em;font-size:clamp(11px,.8vw,15px);font-weight:800;display:none;max-width:min(440px,70vw);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;box-shadow:0 10px 30px #0005}
@media(max-width:1000px){.grid,.grid.compact{grid-template-columns:repeat(3,minmax(0,1fr))}.top{grid-template-columns:74px 1fr 120px}.rank-row{grid-template-columns:55px 54px 90px 1fr 105px}}
@media(max-aspect-ratio:1/1){.grid,.grid.compact{grid-template-columns:repeat(2,minmax(0,1fr))}.podium{grid-template-columns:1fr;height:auto;align-items:stretch}.podium-card{min-height:0!important}.top{grid-template-columns:64px 1fr}.identity{display:none}.event h1{white-space:normal}.rank-row{grid-template-columns:42px 44px 70px 1fr 76px;gap:8px}.call-layout{grid-template-columns:minmax(0,1fr) clamp(170px,27vw,290px);gap:clamp(14px,3vw,34px)}.trophy-showcase img{height:min(39vh,410px)}}
@media(max-width:640px){.call-layout{grid-template-columns:1fr}.trophy-showcase{display:none}}
