<body class="dc-projector-presentation">
<main id="app">
 <header class="top"><div class="logo"><img src="../../public/assets/img/bdc-logo.png" alt="BDC"></div><div class="event"><h1 id="eventName">BDC Dance Cup</h1><p id="categoryName">Holding Screen</p></div><div class="identity"><span class="official <?=$test?'test':''?>"><?=$test?'TEST DISPLAY':'BDC · OFFICIAL LIVE DISPLAY'?></span></div></header>
 <section class="stage" id="stage"><div class="view"><div class="holding"><div class="eyebrow">DANCE CUP</div><h2>Holding Screen</h2><p>Waiting for projection control</p></div></div></section>
 <footer class="footer"><span class="state" id="screenState">Holding Screen</span><span class="page" id="pageState"></span><span class="live"><i class="dot"></i>Live</span></footer>
</main>
<div class="connection" id="connection">Live updates temporarily unavailable. Retrying…</div>
<script>
(()=>{'use strict';
const token=<?=json_encode($token)?>,test=<?=$test?'true':'false'?>,stage=document.getElementById('stage'),eventName=document.getElementById('eventName'),categoryName=document.getElementById('categoryName'),screenState=document.getElementById('screenState'),pageState=document.getElementById('pageState'),connection=document.getElementById('connection');
let lastHash='',busy=false,currentPage=1,pageTotal=1,lastType='holding',nextPageAt=0,backoffUntil=0,cycle={index:0,phase:'contestant',next:0},latest=null;
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const label=value=>String(value||'').replaceAll('_',' ').replace(/\b\w/g,char=>char.toUpperCase());
const chunk=(items,size)=>{const pages=[];for(let index=0;index<items.length;index+=size)pages.push(items.slice(index,index+size));return pages.length?pages:[[]]};
const empty=(title,message)=>'<div class="empty"><strong>'+esc(title)+'</strong><span>'+esc(message)+'</span></div>';
function setHeader(data){document.body.dataset.theme=data.state.theme||'midnight_wine';eventName.textContent=data.state.event_name||'BDC Dance Cup';categoryName.textContent=(data.state.category_name||'Category')+' · '+label(data.state.round_name||'');}
const photo=item=>esc(item?.photo_url||'../../public/assets/img/default-competitor.svg');
const identity=item=>'<div class="identity-meta"><span class="flag">'+esc(item?.flag||'')+'</span><span>'+esc(item?.country||'Country not set')+'</span></div>';
function show(html,type,page=0,total=0){pageTotal=Math.max(1,total||1);stage.innerHTML='<div class="view">'+html+'</div>';screenState.textContent=label(type);pageState.textContent=total>1?'Page '+page+' of '+total:'';}
function holding(data){show('<div class="holding"><div class="eyebrow">'+esc(data.state.holding_title||'DANCE CUP')+'</div><h2>'+esc(data.state.event_name||'BDC Dance Cup')+'</h2><p>'+esc(data.state.holding_message||'Next contestant preparing')+'</p></div>','Holding Screen');}
function contestant(entry){const eventLabel=latest?.state?.event_name||'Dance Cup';show(entry?'<div class="call"><div class="call-layout"><div class="contestant-hero"><img class="profile-photo" src="'+photo(entry)+'" alt=""><div class="label">NOW PRESENTING</div><div class="number">'+esc(entry.contestant_number)+'</div><h2>'+esc(entry.display_name)+'</h2>'+identity(entry)+'</div><aside class="trophy-showcase"><img src="../../public/assets/img/sbta-dance-cup-champion-trophy.png" alt="SBTA Dance Cup trophy"><strong>'+esc(eventLabel)+'</strong></aside></div></div>':empty('Contestant pending','Select a contestant from Projection Control.'),'Contestant Call');}
function pagedCards(items,size,type,renderCard,data){const pages=chunk(items,size),total=pages.length;currentPage=Math.max(1,Math.min(total,currentPage));const cards=pages[currentPage-1].map(renderCard).join('');show(cards?'<div class="grid '+(size>=10?'compact':'')+'">'+cards+'</div>':empty(type+' pending','Add records in the Dance Cup category workspace.'),type,currentPage,total);schedulePage(total,data);}
function judges(data,progress=false){const done=data.judges.filter(j=>j.status==='submitted').length;const cards=j=>'<article class="card judge-card '+(j.status==='submitted'?'submitted':'')+'"><div><img class="profile-photo" src="'+photo(j)+'" alt=""><span class="kicker">J'+esc(j.judge_order)+(Number(j.is_chief)?' · Chief Judge':'')+'</span><strong>'+esc(j.judge_name)+'</strong>'+identity(j)+'<small class="status">'+esc(label(j.status))+'</small></div></article>';if(progress){const pages=chunk(data.judges,8),total=pages.length;currentPage=Math.max(1,Math.min(total,currentPage));show('<div class="progress-wrap"><div class="progress-summary"><span><b>'+done+'</b> completed</span><span class="waiting">'+(data.judges.length-done)+' pending</span></div><div class="grid">'+pages[currentPage-1].map(cards).join('')+'</div></div>','Scoring Progress',currentPage,total);schedulePage(total,data);}else pagedCards(data.judges,8,'Judges',cards,data);}
function contestants(data){pagedCards(data.entries,10,'All Contestants',entry=>'<article class="card"><div><img class="profile-photo" src="'+photo(entry)+'" alt=""><span class="kicker">Contestant</span><strong class="bib">'+esc(entry.contestant_number)+'</strong><small>'+esc(entry.display_name)+'</small>'+identity(entry)+'</div></article>',data);}
function results(data){const pages=chunk(data.results,8),total=pages.length;currentPage=Math.max(1,Math.min(total,currentPage));const rows=pages[currentPage-1].map(row=>{const scored=Number(row.has_score)===1;return '<div class="rank-row"><span class="place">'+(scored?esc(row.placement):'—')+'</span><img class="rank-photo" src="'+photo(row)+'" alt=""><span class="number">No. '+esc(row.contestant_number)+'</span><span class="name">'+esc(row.display_name)+' '+esc(row.flag||'')+'</span><span class="score">'+(scored?Number(row.total_score).toLocaleString(undefined,{maximumFractionDigits:2}):'Not scored')+'</span></div>'}).join('');show(rows?'<div class="board">'+rows+'</div>':empty('Scores pending','Scores will appear after judges begin scoring.'),'Live Scoreboard',currentPage,total);schedulePage(total,data);}
function podium(data){const top=data.results.filter(row=>Number(row.has_score)===1&&row.placement!==null).slice(0,3),order=[top[1],top[0],top[2]],classes=['second','first','third'],medals=['🥈','🥇','🥉'];const cards=order.map((row,index)=>row?'<article class="podium-card '+classes[index]+'"><div class="medal">'+medals[index]+'</div><img class="podium-photo" src="'+photo(row)+'" alt=""><div class="place">'+label(row.placement+(Number(row.placement)===1?'st':Number(row.placement)===2?'nd':'rd'))+'</div><div class="number">No. '+esc(row.contestant_number)+'</div><div class="name">'+esc(row.display_name)+'</div>'+identity(row)+'<div class="score">'+Number(row.total_score).toLocaleString(undefined,{maximumFractionDigits:2})+' points</div></article>':'').join('');show(cards?'<div class="podium">'+cards+'</div>':empty('Podium locked','Calculate results before revealing the winners.'),'Winner Podium');}
function schedulePage(total,data){pageTotal=Math.max(1,total||1);if(total<2){nextPageAt=0;return}if(Number(data.state.auto_page)){if(!nextPageAt)nextPageAt=Date.now()+Math.max(5,Number(data.state.page_delay)||10)*1000}else nextPageAt=0;}
function render(data,force=false){latest=data;setHeader(data);const type=data.state.screen_type||'holding';if(type!==lastType){lastType=type;currentPage=Math.max(1,Number(data.state.page_number)||1);nextPageAt=0}else if(force)currentPage=Math.max(1,Number(data.state.page_number)||currentPage);if(type==='holding')holding(data);else if(type==='contestant')contestant(data.active_entry);else if(type==='contestants')contestants(data);else if(type==='judges')judges(data,false);else if(type==='scoring')judges(data,true);else if(type==='results')results(data);else if(type==='podium')podium(data);else holding(data);}
function advanceAutoPage(){if(!latest||!nextPageAt||Date.now()<nextPageAt)return;currentPage=currentPage>=pageTotal?1:currentPage+1;nextPageAt=0;render(latest);}
function advanceRunOfShow(data){if(!Number(data.state.auto_cycle)||!data.entries.length)return;if(!cycle.next){cycle.index=Math.max(0,data.entries.findIndex(entry=>Number(entry.id)===Number(data.state.active_entry_id)));cycle.phase='contestant';cycle.next=Date.now()+Number(data.state.contestant_seconds||12)*1000}if(Date.now()<cycle.next)return;if(cycle.phase==='contestant'){cycle.phase='holding';cycle.next=Date.now()+Number(data.state.holding_seconds||8)*1000;holding(data)}else{cycle.phase='contestant';cycle.index=(cycle.index+1)%data.entries.length;cycle.next=Date.now()+Number(data.state.contestant_seconds||12)*1000;contestant(data.entries[cycle.index])}}
async function poll(){if(document.hidden||busy||Date.now()<backoffUntil)return;busy=true;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);try{const response=await fetch('./projection-feed.php?token='+encodeURIComponent(token)+(test?'&data_mode=test':'')+'&_='+Date.now(),{cache:'no-store',credentials:'same-origin',headers:{Accept:'application/json'},signal:controller.signal});if(response.status===429){backoffUntil=Date.now()+15000;throw new Error('Rate limited')}const contentType=response.headers.get('content-type')||'';if(!contentType.includes('application/json'))throw new Error('Invalid feed response');const data=await response.json();if(!response.ok||!data.ok)throw new Error('Feed unavailable');const hash=JSON.stringify([data.state.state_version,data.state.screen_type,data.state.theme,data.state.page_number,data.state.auto_page,data.state.page_delay,data.entries,data.judges,data.results,data.active_entry]);if(hash!==lastHash){const stateChanged=lastHash!==''&&latest&&Number(data.state.state_version)!==Number(latest.state.state_version);lastHash=hash;render(data,stateChanged);cycle.next=0}advanceRunOfShow(data);connection.style.display='none'}catch(error){connection.textContent=error?.name==='AbortError'?'Live update timed out. Retrying…':'Live updates interrupted. Retrying…';connection.style.display='block'}finally{clearTimeout(timeout);busy=false}}
setInterval(advanceAutoPage,500);poll();setInterval(poll,5000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll()});
})();
</script>
</body>
</html>
